+  function discover(items) {
+    for (const item of items) {
+      const previous = viable.get(item.name);
+      const narrowed = (previous || catalogs.get(item.name) || []).filter(version => item.accepts(version.tuple));
+      trail.push({ name: item.name, previous });
+      viable.set(item.name, narrowed);
+      queue.push(item.name);
+      const existing = selected.get(item.name);
+      if (existing ? !item.accepts(existing.tuple) : narrowed.length === 0) return false;
+    }
+    return true;
+  }
