  requireRecord(registry);
  const catalogs = new Map();
  for (const name of Object.keys(registry)) {
    const versions = registry[name];
    requireRecord(versions);
    const candidates = Object.keys(versions).map(text => ({
      text, tuple: parse(text), deps: requirements(versions[text]),
    }));
    candidates.sort(candidateOrder);
    catalogs.set(name, candidates);
  }
  const initial = requirements(root);
  const selected = new Map();
  // name -> candidates satisfying every constraint collected so far.
  const viable = new Map();
  // Reversible log of viable-list replacements: { name, previous }.
  const trail = [];
  const queue = [];
  const choices = [];
  let cursor = 0;

  // Records constraints and queues their names; false on a conflict.
  function discover(items) {
