'use strict';
const assert = require('node:assert/strict');
const { resolve } = require('./src');
const { satisfies } = require('./src/semver');

// caret zero majors
assert.equal(satisfies('0.2.9', '^0.2.0'), true);
assert.equal(satisfies('0.3.0', '^0.2.0'), false);
assert.equal(satisfies('0.0.4', '^0.0.3'), false);
assert.equal(satisfies('0.0.3', '^0.0.3'), true);

// backtracking must undo constraints from abandoned branch
const reg1 = {
  a: { '2.0.0': { c: '^2.0.0' }, '1.0.0': { c: '^1.0.0' } },
  b: { '1.0.0': { c: '^1.0.0' } },
  c: { '2.0.0': {}, '1.0.0': {} },
};
assert.deepEqual(resolve(reg1, { a: '*', b: '*' }), { a: '1.0.0', b: '1.0.0', c: '1.0.0' });

// abandoned branch's dependency must not leak into result
const reg2 = {
  a: { '2.0.0': { x: '*', bad: '*' }, '1.0.0': {} },
  x: { '1.0.0': {} },
};
assert.deepEqual(resolve(reg2, { a: '*' }), { a: '1.0.0' });

// cycles
const reg3 = { a: { '1.0.0': { b: '*' } }, b: { '1.0.0': { a: '1.0.0' } } };
assert.deepEqual(resolve(reg3, { a: '*' }), { a: '1.0.0', b: '1.0.0' });

// long chain
const reg4 = {};
const N = 20000;
for (let i = 0; i < N; i++) reg4['p' + i] = { '1.0.0': i + 1 < N ? { ['p' + (i + 1)]: '*' } : {} };
assert.equal(Object.keys(resolve(reg4, { p0: '*' })).length, N);

// deep backtracking: many choices with a conflict at the end
const reg5 = { z: { '1.0.0': {} } };
const M = 30;
for (let i = 0; i < M; i++) reg5['q' + i] = { '2.0.0': {}, '1.0.0': {} };
reg5.end = { '1.0.0': { q0: '1.0.0' } };
const root5 = {};
for (let i = 0; i < M; i++) root5['q' + i] = '*';
root5.end = '*';
const r5 = resolve(reg5, root5);
assert.equal(r5.q0, '1.0.0');
assert.equal(r5.q1, '2.0.0');

// unsat / missing
assert.equal(resolve({ a: { '1.0.0': { m: '*' } } }, { a: '*' }), null);
assert.deepEqual(resolve({}, {}), {});
assert.throws(() => resolve({ u: { 'x': {} } }, {}), TypeError);
assert.throws(() => resolve({}, { a: '' }), TypeError);
console.log('ok');

